#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	traverser(U).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
//
// The core ADI scheme consists of two 1D implicit sweeps per time step:
//  1) "Column" sweep: for each i, solve along j using U to update V, P, Q.
//  2) "Row"    sweep: for each i, solve along j using V to update U, P, Q.
//
// The code below keeps the original numerical scheme and indexing exactly,
// but refactors the traversal to:
//  - re-use traversers and slices instead of constructing them repeatedly
//  - hoist loop-invariant constants out of the inner loops
//  - access elements via Noarr bags and index states only
//
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const std::size_t n = U | get_length<'i'>();
	const std::size_t interior_len = n - 2; // number of interior points per dimension

	// Basic scalar constants
	const num_t zero = SCALAR_VAL(0.0);
	const num_t one  = SCALAR_VAL(1.0);
	const num_t two  = SCALAR_VAL(2.0);

	// Discretization parameters
	const num_t DX = one / static_cast<num_t>(n);
	const num_t DY = one / static_cast<num_t>(n);
	const num_t DT = one / static_cast<num_t>(tsteps);

	const num_t B1  = SCALAR_VAL(2.0);
	const num_t B2  = SCALAR_VAL(1.0);
	const num_t mul1 = B1 * DT / (DX * DX);
	const num_t mul2 = B2 * DT / (DY * DY);

	// Coefficients of the tridiagonal systems
	const num_t a = -mul1 / two;
	const num_t b = one + mul1;
	const num_t c = a;

	const num_t d = -mul2 / two;
	const num_t e = one + mul2;
	const num_t f = d;

	// These combined coefficients appear in every stencil evaluation
	const num_t center_col = one + two * d; // 1 + 2*d, column sweep
	const num_t center_row = one + two * a; // 1 + 2*a, row sweep

	// Proto-structures describing "interior" region (excluding boundary layer)
	const auto interior_i = noarr::slice<'i'>(1, interior_len);
	const auto interior_j = noarr::slice<'j'>(1, interior_len);

	// Base traverser over all 2D fields; we re-order it for individual sweeps
	auto base_trav = traverser(U, V, P, Q);

#pragma scop
	for (std::size_t t = 0; t < tsteps; ++t) {

		// =========================================================
		// 1) Column sweep: for each fixed i, sweep along j
		// =========================================================
		//
		// We iterate i over the interior (1 .. n-2) using for_dims<'i'>,
		// then, for each fixed i, use a 1D traverser along j (1 .. n-2).
		//
		base_trav
			.order(interior_i)
			.template for_dims<'i'>([&](auto trav_i) {
				const auto state_i = trav_i.state();
				const std::size_t i = get_index<'i'>(state_i);

				// Boundary conditions for column i
				const auto v_top  = noarr::idx<'i', 'j'>(0,      i);
				const auto p_i0   = noarr::idx<'i', 'j'>(i,      0);
				const auto q_i0   = p_i0;

				V[v_top] = one;
				P[p_i0]  = zero;
				Q[q_i0]  = V[v_top];

				// 1D traverser along j in the interior (j = 1 .. n-2) for this fixed i
				auto trav_ij = trav_i.order(interior_j);

				// Forward sweep in j: j = 1 .. n-2
				trav_ij.for_each([&](auto state) {
					const auto prev = state - noarr::idx<'j'>(1);
					const std::size_t j = get_index<'j'>(state);

					const num_t denom = a * P[prev] + b;
					P[state] = -c / denom;

					// Note: U is accessed with a "rotated" indexing pattern
					//       U[j][i-1], U[j][i], U[j][i+1]
					const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
					const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i)];
					const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

					Q[state] = (-d * u_j_im1
					            + center_col * u_j_i
					            - f * u_j_ip1
					            - a * Q[prev]) / denom;
				});

				// Bottom boundary for column i
				V[noarr::idx<'i', 'j'>(n - 1, i)] = one;

				// Backward sweep in j: j = n-2 .. 1
				//
				// Noarr's for_each always traverses j in increasing order,
				// so we iterate over an auxiliary index k = 1 .. n-2 and
				// map it to j = n-1-k, yielding j = n-2, n-3, ..., 1.
				//
				trav_ij.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i,     j);
					const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

					V[noarr::idx<'i', 'j'>(j, i)] =
						P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
			});

		// =========================================================
		// 2) Row sweep: for each fixed i, sweep along j
		// =========================================================
		//
		// Same traversal pattern (i then j), but now the implicit
		// system is constructed from V and written back to U.
		//
		base_trav
			.order(interior_i)
			.template for_dims<'i'>([&](auto trav_i) {
				const auto state_i = trav_i.state();
				const std::size_t i = get_index<'i'>(state_i);

				// Boundary conditions for row i
				const auto u_i0 = noarr::idx<'i', 'j'>(i, 0);

				U[u_i0] = one;
				P[u_i0] = zero;
				Q[u_i0] = U[u_i0];

				auto trav_ij = trav_i.order(interior_j);

				// Forward sweep in j: j = 1 .. n-2
				trav_ij.for_each([&](auto state) {
					const auto prev = state - noarr::idx<'j'>(1);
					const std::size_t j = get_index<'j'>(state);

					const num_t denom = d * P[prev] + e;
					P[state] = -f / denom;

					// V stencil in the orthogonal direction:
					// V[i-1][j], V[i][j], V[i+1][j]
					const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
					const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
					const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

					Q[state] = (-a * v_im1_j
					            + center_row * v_i_j
					            - c * v_ip1_j
					            - d * Q[prev]) / denom;
				});

				// Right boundary for row i
				U[noarr::idx<'i', 'j'>(i, n - 1)] = one;

				// Backward sweep in j: j = n-2 .. 1
				trav_ij.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // n-2, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
			});
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
