// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic 2D layout: j is the innermost (contiguous) dimension, i is the outer one.
// This matches the C layout u[i][j] (row-major, contiguous in j).
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
// U: i x j
void init_array(auto U) {
	using namespace noarr;

	const auto n = U | get_length<'i'>();

	// Simple row-major traversal: i outer, j inner (default order for our layout)
	traverser(U).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
// NOTE: all loop nests are expressed via Noarr traversers; explicit indices are
//       derived only from states/traversers, never from raw pointer arithmetic.
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const auto n = U | get_length<'i'>();

	// Scalar parameters of the scheme
	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

	// Extra derived constants used in the stencil; precomputing them
	// avoids recomputing (1 + 2*d) and (1 + 2*a) in the hot loops.
	num_t diag_v = 0; // = 1 + 2*d  (used in column sweep)
	num_t diag_u = 0; // = 1 + 2*a  (used in row sweep)

#pragma scop

	DX = SCALAR_VAL(1.0) / (num_t)n;
	DY = SCALAR_VAL(1.0) / (num_t)n;
	DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = SCALAR_VAL(1.0) + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = SCALAR_VAL(1.0) + mul2;
	f = d;

	diag_v = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d;
	diag_u = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a;

	const std::size_t n_minus1 = n - 1;
	const std::size_t n_minus2 = n - 2;

	// Core interior domain: i, j in [1, n-2]
	// We build these proto-structures once and reuse them inside the time loop
	// to avoid repeatedly constructing identical slice descriptors.
	auto core_i = slice<'i'>(1, n_minus2);
	auto core_j = slice<'j'>(1, n_minus2);

	// Base traverser restricted to interior i: 1 .. n-2.
	// Reused in both column and row sweeps to improve instruction cache locality
	// and avoid redundant traverser construction.
	auto trav_i_base = traverser(U, V, P, Q).order(core_i);

	for (std::size_t t = 1; t <= tsteps; t++) {

		// ---------------------------------------------------------------------
		// Column sweep
		// ---------------------------------------------------------------------
		trav_i_base.template for_dims<'i'>([&](auto trav_i) {
			const auto i = get_index<'i'>(trav_i.state());

			// Fix j-range for this particular i once, and reuse the traverser
			// for the forward and backward sweeps over j.
			auto trav_ij = trav_i.order(core_j);

			// Boundary conditions for column i
			V[noarr::idx<'i', 'j'>(0, i)] = SCALAR_VAL(1.0);
			P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i, 0)] = V[noarr::idx<'i', 'j'>(0, i)];

			// Forward sweep in j: j = 1 .. n-2
			trav_ij.for_each([&](auto state) {
				// state contains ('i' = i, 'j' = current j)
				auto prev = state - noarr::idx<'j'>(1); // ('i' = i, 'j' = j-1)
				const auto j = get_index<'j'>(state);

				const num_t denom = a * P[prev] + b;
				P[state] = -c / denom;

				// NOTE: The original PolyBench kernel uses u[...][...]
				// in a transposed fashion here; we keep the exact indexing
				// semantics, only improving traversal structure.
				const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
				const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i)];
				const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

				Q[state] = (-d * u_j_im1
				            + diag_v * u_j_i
				            - f * u_j_ip1
				            - a * Q[prev]) / denom;
			});

			// Boundary at bottom row
			V[noarr::idx<'i', 'j'>(n_minus1, i)] = SCALAR_VAL(1.0);

			// Backward sweep in j: j = n-2 .. 1
			// Implemented as forward sweep over k = 1 .. n-2 with j = n-1-k
			trav_ij.for_each([&](auto state) {
				const auto k = get_index<'j'>(state);
				const std::size_t j = n_minus1 - k; // n-2, n-3, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		});

		// ---------------------------------------------------------------------
		// Row sweep
		// ---------------------------------------------------------------------
		trav_i_base.template for_dims<'i'>([&](auto trav_i) {
			const auto i = get_index<'i'>(trav_i.state());

			auto trav_ij = trav_i.order(core_j);

			// Boundary conditions for row i
			U[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(1.0);
			P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

			// Forward sweep in j: j = 1 .. n-2
			trav_ij.for_each([&](auto state) {
				auto prev = state - noarr::idx<'j'>(1); // ('i' = i, 'j' = j-1)
				const auto j = get_index<'j'>(state);

				const num_t denom = d * P[prev] + e;
				P[state] = -f / denom;

				const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
				const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
				const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

				Q[state] = (-a * v_im1_j
				            + diag_u * v_i_j
				            - c * v_ip1_j
				            - d * Q[prev]) / denom;
			});

			// Boundary at rightmost column
			U[noarr::idx<'i', 'j'>(i, n_minus1)] = SCALAR_VAL(1.0);

			// Backward sweep in j: j = n-2 .. 1
			trav_ij.for_each([&](auto state) {
				const auto k = get_index<'j'>(state);
				const std::size_t j = n_minus1 - k; // n-2, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		});
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
