#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

/*
 * Layout tuning
 *
 * - U  : row-major in logical indices (i,j) -> contiguous in 'j'
 *        proto: j_vec ^ i_vec  (same as the original code)
 *
 * - V,P,Q : column-major in logical indices (i,j) -> contiguous in 'i'
 *        proto: i_vec ^ j_vec
 *
 * Together with the loop reordering in kernel_adi this improves
 * spatial locality for almost all phases:
 *  - P,Q are always accessed along the recurrence direction and
 *    are now contiguous in the inner loop for both sweeps.
 *  - U is contiguous in the forward column sweep (where it is read
 *    three times per inner iteration).
 *  - V is contiguous in both column and row sweeps.
 */
struct tuning {
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec); // i outer, j inner  (row-major)

	DEFINE_PROTO_STRUCT(v_layout, i_vec ^ j_vec); // j outer, i inner  (column-major)
	DEFINE_PROTO_STRUCT(p_layout, i_vec ^ j_vec);
	DEFINE_PROTO_STRUCT(q_layout, i_vec ^ j_vec);
} tuning;


// initialization function (unchanged)
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	traverser(U).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
//
// Compared to the original version, this kernel performs the same
// arithmetic but uses a different (legally equivalent) loop order
// and slightly different layouts (see `tuning` above) in order to
// improve data locality:
//
//  - All recurrences in j are now implemented as nested loops
//    "for j (outer) { for i (inner) { ... } }" using
//    traverser.for_dims<'j'> + inner for_each.
//
//  - P, Q, and V are laid out column-major (contiguous in 'i') so
//    that the inner loop over i accesses them with unit stride.
//
//  - U is left in row-major, which makes the forward column sweep's
//    accesses to U contiguous; only the final backward row sweep
//    uses U with a stride.
//
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

#pragma scop

	DX = SCALAR_VAL(1.0) / (num_t)n;
	DY = SCALAR_VAL(1.0) / (num_t)n;
	DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = SCALAR_VAL(1.0) + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = SCALAR_VAL(1.0) + mul2;
	f = d;

	// Proto-structures describing the interior (1..n-2 in both dims).
	auto inner_i = noarr::slice<'i'>(1, n - 2);
	auto inner_j = noarr::slice<'j'>(1, n - 2);
	auto interior = inner_i ^ inner_j;

	for (std::size_t t = 1; t <= tsteps; t++) {

		// -------------------------------------------------------------
		// Column sweep (tri-diagonal systems along "j", one for each i)
		// -------------------------------------------------------------

		// 1) Column boundary at the top: j = 0, i = 1..n-2
		//    v[0][i] = 1;  p[i][0] = 0;  q[i][0] = v[0][i];
		traverser(V, P, Q)
			.order(inner_i)
			.template for_dims<'i'>([=](auto trav_i) {
				auto i = get_index<'i'>(trav_i.state());

				auto v0i_state = noarr::idx<'i', 'j'>(0, i);
				auto pi0_state = noarr::idx<'i', 'j'>(i, 0);

				V[v0i_state] = SCALAR_VAL(1.0);
				P[pi0_state] = SCALAR_VAL(0.0);
				Q[pi0_state] = V[v0i_state];
			});

		// 2) Forward sweep in j: j = 1 .. n-2 (outer), i = 1 .. n-2 (inner)
		//
		//    p[i][j] = -c / (a*p[i][j-1] + b);
		//    q[i][j] = (-d*u[j-1][i] + (1 + 2*d)*u[j][i] - f*u[j+1][i]
		//               - a*q[i][j-1]) / (a*p[i][j-1] + b);
		traverser(U, V, P, Q)
			.order(interior)
			.template for_dims<'j'>([=](auto trav_j) {
				auto j = get_index<'j'>(trav_j.state());

				trav_j.for_each([=](auto state) {
					auto i = get_index<'i'>(state);

					// state has (i, j); prev has (i, j-1)
					auto prev = state - noarr::idx<'j'>(1);

					num_t denom = a * P[prev] + b;
					P[state] = -c / denom;

					// U is stored row-major in (i,j), but here we use U[j][i]
					// (i.e., transposed indices). With layout j_vec^i_vec
					// and inner loop over i, these accesses are contiguous.
					num_t u_jm1_i = U[noarr::idx<'i', 'j'>(j - 1, i)];
					num_t u_j_i   = U[noarr::idx<'i', 'j'>(j,     i)];
					num_t u_jp1_i = U[noarr::idx<'i', 'j'>(j + 1, i)];

					Q[state] = (-d * u_jm1_i
					            + (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d) * u_j_i
					            - f * u_jp1_i
					            - a * Q[prev]) / denom;
				});
			});

		// 3) Column boundary at the bottom: j = n-1, i = 1..n-2
		//    v[n-1][i] = 1;
		traverser(V)
			.order(inner_i)
			.template for_dims<'i'>([=](auto trav_i) {
				auto i = get_index<'i'>(trav_i.state());
				V[noarr::idx<'i', 'j'>(n - 1, i)] = SCALAR_VAL(1.0);
			});

		// 4) Backward sweep in j: j = n-2 .. 1
		//
		// We implement this as k = 1..n-2 with j = n-1-k:
		//    v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
		traverser(P, Q)
			.order(interior)
			.template for_dims<'j'>([=](auto trav_k) {
				auto k = get_index<'j'>(trav_k.state());
				std::size_t j = n - 1 - k; // runs n-2, ..., 1

				trav_k.for_each([=](auto state_ik) {
					auto i = get_index<'i'>(state_ik);

					auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

					V[noarr::idx<'i', 'j'>(j, i)] =
						P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
			});

		// ----------------------------------------------------------
		// Row sweep (tri-diagonal systems along "j", one for each i)
		// ----------------------------------------------------------

		// 1) Row boundary on the left: j = 0, i = 1..n-2
		//    u[i][0] = 1;  p[i][0] = 0;  q[i][0] = u[i][0];
		traverser(U, P, Q)
			.order(inner_i)
			.template for_dims<'i'>([=](auto trav_i) {
				auto i = get_index<'i'>(trav_i.state());

				auto ui0_state = noarr::idx<'i', 'j'>(i, 0);

				U[ui0_state] = SCALAR_VAL(1.0);
				P[ui0_state] = SCALAR_VAL(0.0);
				Q[ui0_state] = U[ui0_state];
			});

		// 2) Forward sweep in j: j = 1 .. n-2 (outer), i = 1 .. n-2 (inner)
		//
		//    p[i][j] = -f / (d*p[i][j-1] + e);
		//    q[i][j] = (-a*v[i-1][j] + (1 + 2*a)*v[i][j] - c*v[i+1][j]
		//               - d*q[i][j-1]) / (d*p[i][j-1] + e);
		traverser(U, V, P, Q)
			.order(interior)
			.template for_dims<'j'>([=](auto trav_j) {
				auto j = get_index<'j'>(trav_j.state());

				trav_j.for_each([=](auto state) {
					auto i = get_index<'i'>(state);

					auto prev = state - noarr::idx<'j'>(1);

					num_t denom = d * P[prev] + e;
					P[state] = -f / denom;

					// V is stored column-major (i_vec ^ j_vec), and here
					// we access v[i-1][j], v[i][j], v[i+1][j] with i as
				 // the inner-loop index -> contiguous in memory.
					num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
					num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
					num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

					Q[state] = (-a * v_im1_j
					            + (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a) * v_i_j
					            - c * v_ip1_j
					            - d * Q[prev]) / denom;
				});
			});

		// 3) Row boundary on the right: j = n-1, i = 1..n-2
		//    u[i][n-1] = 1;
		traverser(U)
			.order(inner_i)
			.template for_dims<'i'>([=](auto trav_i) {
				auto i = get_index<'i'>(trav_i.state());
				U[noarr::idx<'i', 'j'>(i, n - 1)] = SCALAR_VAL(1.0);
			});

		// 4) Backward sweep in j: j = n-2 .. 1
		//
		// Implemented as k = 1..n-2 with j = n-1-k:
		//    u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
		traverser(P, Q)
			.order(interior)
			.template for_dims<'j'>([=](auto trav_k) {
				auto k = get_index<'j'>(trav_k.state());
				std::size_t j = n - 1 - k; // n-2, ..., 1

				trav_k.for_each([=](auto state_ik) {
					auto i = get_index<'i'>(state_ik);

					auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
			});
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
