// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic building blocks for tuning the layout of individual arrays.
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Layout tuning for all fields.
//
// NOTE:
//   We keep the original choice (j_vec inner, i_vec outer), which matches
//   the classic C layout `u[i][j]` with `j` as the fast-varying index.
//   More aggressive tuning (e.g. different layouts for U/V/P/Q) is possible,
//   but this uniform layout already gives good spatial locality for
//   sweeps where `j` is the inner loop.
struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	// Use a single traverser; keep j as the inner loop for good locality.
	traverser(U).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

#pragma scop

	// --------------------------------------------------------------------
	// Precompute scalar coefficients (basic ADI discretization constants)
	// --------------------------------------------------------------------
	DX = SCALAR_VAL(1.0) / (num_t)n;
	DY = SCALAR_VAL(1.0) / (num_t)n;
	DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = SCALAR_VAL(1.0) + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = SCALAR_VAL(1.0) + mul2;
	f = d;

	// Frequently used composite coefficients; hoisted out of inner loops.
	const num_t one_plus_2d = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d;
	const num_t one_plus_2a = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a;

	// Reusable views describing the interior domain 1 .. n-2 in each dimension.
	const auto interior_i = noarr::slice<'i'>(1, n - 2);
	const auto interior_j = noarr::slice<'j'>(1, n - 2);

	for (std::size_t t = 1; t <= tsteps; t++) {
		// ================================================================
		// Column sweep
		// ================================================================
		//
		// For each interior column i:
		//   1) Set column-wise boundary conditions in V, P, Q.
		//   2) Do a forward sweep in j (1 .. n-2) on P and Q.
		//   3) Set bottom boundary in V.
		//   4) Do a backward sweep in j (n-2 .. 1) to compute V.
		//
		traverser(U, V, P, Q)
			.order(interior_i)
			.template for_dims<'i'>([&](auto trav_i) {
				auto i = get_index<'i'>(trav_i.state());

				// ----------------------------
				// Boundary conditions (column)
				// ----------------------------
				const auto v_top_state  = noarr::idx<'i', 'j'>(0, i);   // V[0][i]
				const auto p_base_state = noarr::idx<'i', 'j'>(i, 0);   // P[i][0]

				V[v_top_state]  = SCALAR_VAL(1.0);
				P[p_base_state] = SCALAR_VAL(0.0);
				Q[p_base_state] = V[v_top_state];

				// ---------------------------------------------------------
				// Forward sweep in j: j = 1 .. n-2  (Thomas algorithm step)
				// ---------------------------------------------------------
				trav_i.order(interior_j).for_each([&](auto state) {
					// state has fixed i and varying j in [1, n-2]
					auto prev = state - noarr::idx<'j'>(1); // (i, j-1)

					const auto j = get_index<'j'>(state);

					const num_t denom = a * P[prev] + b;
					P[state] = -c / denom;

					// Read U along the "orthogonal" direction:
					//   u[j-1][i], u[j][i], u[j+1][i]
					const std::size_t j_minus_1 = j - 1;
					const std::size_t j_plus_1  = j + 1;

					const auto u_j_im1_state = noarr::idx<'i', 'j'>(j_minus_1, i);
					const auto u_j_i_state   = noarr::idx<'i', 'j'>(j,        i);
					const auto u_j_ip1_state = noarr::idx<'i', 'j'>(j_plus_1, i);

					const num_t u_j_im1 = U[u_j_im1_state];
					const num_t u_j_i   = U[u_j_i_state];
					const num_t u_j_ip1 = U[u_j_ip1_state];

					Q[state] = (-d * u_j_im1
					            + one_plus_2d * u_j_i
					            - f * u_j_ip1
					            - a * Q[prev]) / denom;
				});

				// ---------------------------
				// Bottom boundary in V
				// ---------------------------
				V[noarr::idx<'i', 'j'>(n - 1, i)] = SCALAR_VAL(1.0);

				// ---------------------------------------------------------
				// Backward sweep in j: j = n-2 .. 1
				// Implemented as a forward sweep over k = 1 .. n-2
				// with j = n-1-k, so that dependence on V[j+1][i]
				// is always satisfied.
				// ---------------------------------------------------------
				trav_i.order(interior_j).for_each([&](auto state) {
					const auto k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // j: n-2, n-3, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);
					const auto vji_state   = noarr::idx<'i', 'j'>(j, i);

					V[vji_state] = P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
			});

		// ================================================================
		// Row sweep
		// ================================================================
		//
		// For each interior row i:
		//   1) Set row-wise boundary conditions in U, P, Q.
		//   2) Do a forward sweep in j (1 .. n-2) on P and Q.
		//   3) Set right boundary in U.
		//   4) Do a backward sweep in j (n-2 .. 1) to update U.
		//
		traverser(U, V, P, Q)
			.order(interior_i)
			.template for_dims<'i'>([&](auto trav_i) {
				auto i = get_index<'i'>(trav_i.state());

				// -------------------------
				// Boundary conditions (row)
				// -------------------------
				const auto u_left_state = noarr::idx<'i', 'j'>(i, 0); // U[i][0]

				U[u_left_state] = SCALAR_VAL(1.0);
				P[u_left_state] = SCALAR_VAL(0.0);
				Q[u_left_state] = U[u_left_state];

				// ---------------------------------------------------------
				// Forward sweep in j: j = 1 .. n-2
				// ---------------------------------------------------------
				trav_i.order(interior_j).for_each([&](auto state) {
					auto prev = state - noarr::idx<'j'>(1); // (i, j-1)

					const auto j = get_index<'j'>(state);

					const num_t denom = d * P[prev] + e;
					P[state] = -f / denom;

					// Read V in the orthogonal direction:
					//   v[i-1][j], v[i][j], v[i+1][j]
					const auto v_im1_j_state = noarr::idx<'i', 'j'>(i - 1, j);
					const auto v_i_j_state   = noarr::idx<'i', 'j'>(i,     j);
					const auto v_ip1_j_state = noarr::idx<'i', 'j'>(i + 1, j);

					const num_t v_im1_j = V[v_im1_j_state];
					const num_t v_i_j   = V[v_i_j_state];
					const num_t v_ip1_j = V[v_ip1_j_state];

					Q[state] = (-a * v_im1_j
					            + one_plus_2a * v_i_j
					            - c * v_ip1_j
					            - d * Q[prev]) / denom;
				});

				// --------------------------
				// Right boundary in U
				// --------------------------
				U[noarr::idx<'i', 'j'>(i, n - 1)] = SCALAR_VAL(1.0);

				// ---------------------------------------------------------
				// Backward sweep in j: j = n-2 .. 1
				// Implemented via forward sweep over k = 1 .. n-2
				// with j = n-1-k.
				// ---------------------------------------------------------
				trav_i.order(interior_j).for_each([&](auto state) {
					const auto k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // j: n-2, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
			});
	}

#pragma endscop
}

